edit('scripts/ask.html', 1, '<meta charset="utf-8"/>\n<meta name="viewport" content="width=device-width,initial-scale=1"/>\n<title>Ask the Corpus \u2014 Srangam</title>\n<link rel="preconnect" href="https://fonts.googleapis.com"/>\n<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin/>\n<link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&family=Cormorant+Garamond:ital,wght@0,500;0,600;1,500&family=JetBrains+Mono:wght@400;500&display=swap" rel="stylesheet"/>\n<style>\n  :root{\n    --bg:#100e0b; --bg2:#17140f; --bg3:#1e1a14; --bg4:#26211a;\n    --ink:#ece4d4; --muted:#9b8f7a; --faint:#6b6151;\n    --gold:#e0b062; --gold-dim:#7a5f2e; --border:#2a241b; --border-v:#332c22;\n    --green:#7bbf6a; --red:#d98b6a;\n  }\n  *{box-sizing:border-box}\n  html,body{margin:0;background:var(--bg);color:var(--ink);\n    font-family:"Inter",system-ui,sans-serif;font-size:15px;line-height:1.6}\n  a{color:var(--gold);text-decoration:none}\n  .wrap{max-width:900px;margin:0 auto;padding:0 22px 80px}\n  header{display:flex;align-items:center;gap:14px;padding:22px 0 14px;flex-wrap:wrap}\n  .om{font-family:"Cormorant Garamond",serif;font-size:30px;color:var(--gold);font-weight:600}\n  .title{font-family:"Cormorant Garamond",serif;font-size:26px;font-weight:600;color:var(--gold)}\n  .sub{color:var(--muted);font-size:12.5px}\n  .nav{margin-left:auto;display:flex;gap:6px}\n  .nav a{font-size:12.5px;color:var(--muted);border:1px solid var(--border-v);\n    padding:5px 11px;border-radius:7px}\n  .nav a:hover{color:var(--gold);border-color:var(--gold-dim)}\n  .askbox{background:var(--bg2);border:1px solid var(--border-v);border-radius:14px;\n    padding:16px;margin-top:8px}\n  textarea{width:100%;background:var(--bg3);border:1px solid var(--border-v);color:var(--ink);\n    border-radius:10px;padding:12px 14px;font-family:inherit;font-size:15px;resize:vertical;\n    min-height:70px;line-height:1.5}\n  textarea:focus{outline:none;border-color:var(--gold-dim)}\n  .controls{display:flex;align-items:center;gap:12px;margin-top:12px;flex-wrap:wrap}\n  select,.kwrap{background:var(--bg3);border:1px solid var(--border-v);color:var(--ink);\n    border-radius:8px;padding:8px 10px;font-family:"JetBrains Mono",monospace;font-size:12.5px}\n  .kwrap{display:flex;align-items:center;gap:8px;color:var(--muted)}\n  .kwrap input{accent-color:var(--gold)}\n  label.lbl{color:var(--faint);font-size:10.5px;text-transform:uppercase;letter-spacing:.06em;\n    font-weight:600;margin-right:2px}\n  .ask-btn{margin-left:auto;background:linear-gradient(135deg,var(--gold),#c8922f);\n    color:#1a1509;border:none;border-radius:9px;padding:10px 22px;font-weight:700;font-size:14px;\n    cursor:pointer;font-family:inherit}\n  .ask-btn:hover{filter:brightness(1.06)}\n  .ask-btn:disabled{opacity:.5;cursor:default}\n  .hint{color:var(--faint);font-size:12px;margin-top:10px}\n  .hint b{color:var(--muted);font-weight:600}\n  .chip{display:inline-block;background:var(--bg3);border:1px solid var(--border-v);\n    color:var(--muted);border-radius:20px;padding:3px 11px;font-size:12px;cursor:pointer;\n    margin:4px 6px 0 0}\n  .chip:hover{color:var(--gold);border-color:var(--gold-dim)}\n  #status{margin-top:18px;color:var(--muted);font-size:13.5px;display:none}\n  .spinner{display:inline-block;width:13px;height:13px;border:2px solid var(--border-v);\n    border-top-color:var(--gold);border-radius:50%;animation:spin .8s linear infinite;\n    vertical-align:-2px;margin-right:8px}\n  @keyframes spin{to{transform:rotate(360deg)}}\n  .answer{margin-top:22px;display:none}\n  .answer-body{background:var(--bg2);border:1px solid var(--border-v);border-left:3px solid var(--gold);\n    border-radius:12px;padding:18px 20px;font-size:15.5px;line-height:1.72;white-space:pre-wrap}\n  .answer-body .cite{color:var(--gold);background:rgba(224,176,98,.11);border:1px solid var(--gold-dim);\n    border-radius:5px;padding:0 5px;font-family:"JetBrains Mono",monospace;font-size:12.5px;\n    cursor:pointer;white-space:nowrap}\n  .meta{color:var(--faint);font-size:11.5px;margin-top:8px;font-family:"JetBrains Mono",monospace}\n  h3.srch{color:var(--muted);font-size:12px;text-transform:uppercase;letter-spacing:.08em;\n    font-weight:600;margin:26px 0 10px}\n  .src{background:var(--bg2);border:1px solid var(--border);border-radius:10px;padding:12px 14px;\n    margin-bottom:9px;display:block;transition:border-color .15s}\n  .src:target,.src.flash{border-color:var(--gold);box-shadow:0 0 0 1px var(--gold-dim)}\n  .src:hover{border-color:var(--border-v)}\n  .src .tag{font-family:"JetBrains Mono",monospace;font-size:12px;color:var(--gold);font-weight:500}\n  .src .num{color:var(--faint);font-family:"JetBrains Mono",monospace;font-size:11px;margin-right:8px}\n  .src .en{color:var(--ink);font-size:14px;margin-top:5px;font-family:"Cormorant Garamond",serif;\n    font-size:16px;line-height:1.5}\n  .src .open{float:right;color:var(--muted);font-size:11px}\n  .err{color:var(--red);background:rgba(217,139,106,.08);border:1px solid #6b3a2a;\n    border-radius:8px;padding:12px 14px;margin-top:16px;font-size:13.5px}\n  footer{color:var(--faint);font-size:11.5px;margin-top:40px;text-align:center;line-height:1.7}\n</style>\n</head>\n<body>\n<div class="wrap">\n  <header>\n    <span class="om">&#x0950;</span>\n    <div>\n      <div class="title">Ask the Corpus</div>\n      <div class="sub">Retrieval-augmented Q&amp;A over the translated Sanskrit corpus &mdash; grounded in verses, cited by reference</div>\n    </div>\n    <nav class="nav">\n      <a href="/">&#8592; Dashboard</a>\n      <a href="/library">&#128218; Library</a>\n    </nav>\n  </header>\n\n  <div class="askbox">\n    <textarea id="q" placeholder="Ask a question about the scriptures&hellip;  e.g.  What does the corpus say about the origin of the river Ga\u1e45g\u0101?"></textarea>\n    <div class="controls">\n      <label class="lbl">Engine</label>\n      <select id="engine">\n        <option value="gemini:gemini-2.5-flash" selected>&#x26A1; 2.5 Flash</option>\n        <option value="gemini:gemini-2.5-pro">&#x2726; 2.5 Pro (deeper)</option>\n        <option value="gemini:gemini-2.0-flash">&#x26A1; 2.0 Flash</option>\n      </select>\n      <span class="kwrap"><label class="lbl">Passages</label>\n        <input type="range" id="k" min="4" max="24" value="12" oninput="kv.textContent=this.value"/>\n        <b id="kv" style="color:var(--gold)">12</b></span>\n      <button class="ask-btn" id="askBtn" onclick="ask()">Ask &#8594;</button>\n    </div>\n    <div class="hint">\n      <b>How it works:</b> full-text search finds the most relevant translated verses, then the model answers\n      <b>using only those verses</b> and cites each one. It will say when the corpus doesn&rsquo;t contain the answer &mdash; it does not invent.\n      <div>\n        <span class="chip" onclick="setQ(this)">the duties of a king toward his subjects</span>\n        <span class="chip" onclick="setQ(this)">what is said about Naimi\u1e63\u0101ra\u1e47ya</span>\n        <span class="chip" onclick="setQ(this)">how did the rivers become goddesses</span>\n      </div>\n    </div>\n  </div>\n\n  <div id="status"></div>\n  <div id="errBox"></div>\n\n  <div class="answer" id="answer">\n    <div class="answer-body" id="answerBody"></div>\n    <div class="meta" id="answerMeta"></div>\n    <h3 class="srch">Sources &mdash; the verses this answer is grounded in</h3>\n    <div id="sources"></div>\n  </div>\n\n  <footer>\n    Answers are generated from the corpus translations and may reflect their limits.<br/>\n    Always verify against the cited verses in the reader.\n  </footer>\n</div>\n\n<script>\n  var LAST_SOURCES = [];\n  try { var e = localStorage.getItem(\'askEngine\'); if (e) document.getElementById(\'engine\').value = e; } catch(_){}\n  document.getElementById(\'engine\').addEventListener(\'change\', function(){\n    try { localStorage.setItem(\'askEngine\', this.value); } catch(_){}\n  });\n  document.getElementById(\'q\').addEventListener(\'keydown\', function(ev){\n    if (ev.key === \'Enter\' && (ev.ctrlKey || ev.metaKey)) { ev.preventDefault(); ask(); }\n  });\n  function setQ(el){ document.getElementById(\'q\').value = el.textContent; document.getElementById(\'q\').focus(); }\n  function esc(s){ return (s==null?\'\':String(s)).replace(/[&<>"]/g, function(c){\n    return {\'&\':\'&amp;\',\'<\':\'&lt;\',\'>\':\'&gt;\',\'"\':\'&quot;\'}[c]; }); }\n\n  function renderAnswer(text){\n    // Highlight [tag] citations and make them jump to the matching source card.\n    var html = esc(text).replace(/\\[([^\\]]+)\\]/g, function(m, tag){\n      var idx = LAST_SOURCES.findIndex(function(s){ return s.tag === tag.trim(); });\n      if (idx >= 0) return \'<span class="cite" onclick="jumpSrc(\'+(idx+1)+\')">[\'+esc(tag)+\']</span>\';\n      return \'<span class="cite">[\'+esc(tag)+\']</span>\';\n    });\n    document.getElementById(\'answerBody\').innerHTML = html;\n  }\n  function jumpSrc(n){\n    var el = document.getElementById(\'src-\'+n);\n    if (!el) return;\n    el.scrollIntoView({behavior:\'smooth\', block:\'center\'});\n    el.classList.add(\'flash\'); setTimeout(function(){ el.classList.remove(\'flash\'); }, 1400);\n  }\n  function renderSources(sources){\n    LAST_SOURCES = sources || [];\n    var html = \'\';\n    (sources||[]).forEach(function(s){\n      // BRAIN_ITEMS_2026_10_07: an editorial item opens its story, episode or picture\n      html += \'<a class="src" id="src-\'+s.n+\'" href="\'+(s.link ? esc(s.link) : \'/reader/\'+encodeURIComponent(s.doc))+\'" target="_blank">\'\n            + \'<span class="open">\'+(s.link ? \'open &#8599;\' : \'open in reader &#8599;\')+\'</span>\'\n            + \'<span class="num">\'+s.n+\'</span><span class="tag">[\'+esc(s.tag)+\']</span>\'\n            + (s.label ? \' <i style="color:#b18a45">\'+esc(s.label)+\'</i>\' : \'\')\n            + \'<div class="en">\'+esc(s.english||\'\')+\'</div></a>\';\n    });\n    document.getElementById(\'sources\').innerHTML = html;\n  }\n\n  async function ask(){\n    var q = document.getElementById(\'q\').value.trim();\n    var errBox = document.getElementById(\'errBox\'); errBox.innerHTML = \'\';\n    if (!q){ document.getElementById(\'q\').focus(); return; }\n    var btn = document.getElementById(\'askBtn\'); btn.disabled = true;\n    var st = document.getElementById(\'status\'); st.style.display = \'block\';\n    st.innerHTML = \'<span class="spinner"></span>Searching the corpus and composing a grounded answer&hellip;\';\n    document.getElementById(\'answer\').style.display = \'none\';\n    try{\n      var r = await fetch(\'/api/ask\', {\n        method:\'POST\', headers:{\'Content-Type\':\'application/json\'},\n        body: JSON.stringify({ q: q, engine: document.getElementById(\'engine\').value,\n                               k: parseInt(document.getElementById(\'k\').value,10) })\n      });\n      var d = await r.json();\n      st.style.display = \'none\';\n      if (!r.ok || d.error){\n        errBox.innerHTML = \'<div class="err"><b>Could not answer:</b> \'+esc(d.error||(\'HTTP \'+r.status))\n          + (d.error && d.error.indexOf(\'GEMINI_API_KEY\')>=0\n             ? \'<br/>Set <code>GEMINI_API_KEY</code> in the project <code>.env</code> and restart the dashboard.\' : \'\')\n          +\'</div>\';\n        if (d.sources && d.sources.length){ renderSources(d.sources);\n          document.getElementById(\'answerBody\').innerHTML = \'<i style="color:var(--muted)">Retrieved passages are shown below.</i>\';\n          document.getElementById(\'answerMeta\').textContent = \'\';\n          document.getElementById(\'answer\').style.display = \'block\'; }\n        return;\n      }\n      renderSources(d.sources);\n      renderAnswer(d.answer||\'\');\n      var modeLabel = d.mode === \'semantic\' ? \'\u25c9 semantic (meaning) search\'\n                     : \'\u25cb keyword search\';\n      document.getElementById(\'answerMeta\').textContent =\n        (d.sources? d.sources.length : 0) + \' passages retrieved \xb7 \' + modeLabel + \' \xb7 engine \' + (d.engine||\'\');\n      document.getElementById(\'answer\').style.display = \'block\';\n      document.getElementById(\'answer\').scrollIntoView({behavior:\'smooth\', block:\'start\'});\n    }catch(e){\n      st.style.display = \'none\';\n      errBox.innerHTML = \'<div class="err">Request failed: \'+esc(e.message||e)+\'</div>\';\n    }finally{ btn.disabled = false; }\n  }\n</script>\n</body>',
     '<meta charset="utf-8"/>\n<meta name="viewport" content="width=device-width,initial-scale=1"/>\n<title>Ask the Corpus &mdash; Srangam</title>\n<!-- ASK_UI_2026_10_22: one Ask page (U1, docs/RELATIONS_AND_ASK_2026-10-22.md). The answer with numbered citations; the\n     verses beside it in Devanagari, IAST and English (the scholarly English first, where it passed), with their\n     standing and the names they name. It reads /api/ask as before: a field the dashboard does not send is left out. -->\n<link rel="preconnect" href="https://fonts.googleapis.com"/>\n<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin/>\n<link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&family=Cormorant+Garamond:ital,wght@0,500;0,600;1,500&family=Noto+Serif+Devanagari:wght@400;500;600&family=JetBrains+Mono:wght@400;500&display=swap" rel="stylesheet"/>\n<style>\n  :root{\n    --bg:#100e0b; --bg2:#17140f; --bg3:#1e1a14; --bg4:#26211a;\n    --ink:#ece4d4; --muted:#a3967f; --faint:#756a58;\n    --gold:#e0b062; --gold-dim:#7a5f2e; --border:#2a241b; --border-v:#3a3226;\n    --green:#7bbf6a; --red:#d98b6a; --violet:#c3a6e8; --violet-dim:#5a4380; --blue:#8fb4de;\n    --dev:"Noto Serif Devanagari","Nirmala UI",serif; --serif:"Cormorant Garamond",Georgia,serif;\n    --mono:"JetBrains Mono",ui-monospace,monospace;\n  }\n  *{box-sizing:border-box}\n  [hidden]{display:none!important}\n  html,body{margin:0;background:var(--bg);color:var(--ink);font-family:"Inter",system-ui,sans-serif;font-size:15px;\n    line-height:1.6}\n  a{color:var(--gold);text-decoration:none}\n  a:hover{text-decoration:underline}\n  button{font-family:inherit}\n  :focus-visible{outline:2px solid var(--gold);outline-offset:2px}\n  .wrap{max-width:1320px;margin:0 auto;padding:0 20px 64px}\n  header.top{display:flex;align-items:center;gap:14px;padding:18px 0 12px;flex-wrap:wrap}\n  .om{font-family:var(--dev);font-size:30px;color:var(--gold)}\n  .title{font-family:var(--serif);font-size:27px;font-weight:600;color:var(--gold);line-height:1.1}\n  .sub{color:var(--muted);font-size:12.5px}\n  .nav{margin-left:auto;display:flex;gap:6px;flex-wrap:wrap}\n  .nav a{font-size:12.5px;color:var(--muted);border:1px solid var(--border-v);padding:5px 11px;border-radius:7px}\n  .nav a:hover{color:var(--gold);border-color:var(--gold-dim);text-decoration:none}\n  .askbox{background:var(--bg2);border:1px solid var(--border-v);border-radius:14px;padding:14px;max-width:980px}\n  textarea{width:100%;background:var(--bg3);border:1px solid var(--border-v);color:var(--ink);border-radius:10px;\n    padding:12px 14px;font-family:inherit;font-size:15.5px;resize:vertical;min-height:64px;line-height:1.5}\n  textarea:focus{outline:none;border-color:var(--gold-dim)}\n  .controls{display:flex;align-items:center;gap:10px;margin-top:10px;flex-wrap:wrap}\n  select,.kwrap{background:var(--bg3);border:1px solid var(--border-v);color:var(--ink);border-radius:8px;\n    padding:7px 9px;font-family:var(--mono);font-size:12.5px}\n  .kwrap{display:flex;align-items:center;gap:8px;color:var(--muted)}\n  .kwrap input{accent-color:var(--gold);width:110px}\n  .lbl{color:var(--faint);font-size:10.5px;text-transform:uppercase;letter-spacing:.06em;font-weight:600}\n  .keys{color:var(--faint);font-size:11.5px}\n  .keys kbd{font-family:var(--mono);font-size:10.5px;border:1px solid var(--border-v);border-radius:4px;padding:0 4px;\n    color:var(--muted)}\n  .ask-btn{margin-left:auto;background:linear-gradient(135deg,var(--gold),#c8922f);color:#1a1509;border:none;\n    border-radius:9px;padding:10px 22px;font-weight:700;font-size:14px;cursor:pointer}\n  .ask-btn:hover{filter:brightness(1.06)}\n  .ask-btn:disabled{opacity:.5;cursor:default}\n  .chips{margin-top:10px;display:flex;flex-wrap:wrap;gap:6px;align-items:center}\n  .chip{background:var(--bg3);border:1px solid var(--border-v);color:var(--muted);border-radius:20px;padding:3px 11px;\n    font-size:12px;cursor:pointer}\n  .chip:hover{color:var(--gold);border-color:var(--gold-dim)}\n  .chip.clear{border-style:dashed}\n  #status{margin-top:16px;color:var(--muted);font-size:13.5px;min-height:1px}\n  .spinner{display:inline-block;width:13px;height:13px;border:2px solid var(--border-v);border-top-color:var(--gold);\n    border-radius:50%;animation:spin .8s linear infinite;vertical-align:-2px;margin-right:8px}\n  @keyframes spin{to{transform:rotate(360deg)}}\n  .err{color:var(--red);background:rgba(217,139,106,.08);border:1px solid #6b3a2a;border-radius:8px;padding:12px 14px;\n    margin-top:14px;font-size:13.5px;max-width:980px}\n  .result{display:grid;grid-template-columns:minmax(0,1fr);gap:18px;margin-top:18px}\n  @media (min-width:1100px){\n    .result{grid-template-columns:minmax(0,1.08fr) minmax(0,1fr);align-items:start}\n    .sources-col{position:sticky;top:12px;max-height:calc(100vh - 24px);overflow:auto;padding-right:4px}\n  }\n  .panel-head{display:flex;align-items:center;gap:10px;flex-wrap:wrap;margin:0 0 8px}\n  .panel-head h2{font-size:12px;text-transform:uppercase;letter-spacing:.08em;color:var(--muted);font-weight:600;margin:0}\n  .panel-head .grow{flex:1}\n  .tbtn{background:var(--bg3);border:1px solid var(--border-v);color:var(--muted);border-radius:7px;padding:3px 9px;\n    font-size:11.5px;cursor:pointer}\n  .tbtn[aria-pressed="true"]{color:var(--gold);border-color:var(--gold-dim);background:rgba(224,176,98,.08)}\n  .tbtn:hover{color:var(--gold)}\n  .answer-body{background:var(--bg2);border:1px solid var(--border-v);border-left:3px solid var(--gold);\n    border-radius:12px;padding:16px 20px;font-size:15.5px;line-height:1.75}\n  .answer-body p{margin:0 0 .8em}\n  .answer-body p:last-child{margin-bottom:0}\n  .answer-body h4{font-size:14px;color:var(--gold);margin:1em 0 .4em;letter-spacing:.02em}\n  .answer-body ul,.answer-body ol{margin:.2em 0 .9em;padding-left:1.4em}\n  .answer-body li{margin:.2em 0}\n  .cite{display:inline-block;min-width:1.55em;text-align:center;color:var(--gold);background:rgba(224,176,98,.11);\n    border:1px solid var(--gold-dim);border-radius:5px;padding:0 4px;font-family:var(--mono);font-size:11.5px;\n    line-height:1.45;cursor:pointer;vertical-align:1px;margin:0 1px}\n  .cite:hover,.cite.lit{background:rgba(224,176,98,.28);text-decoration:none}\n  .cite.unknown{color:var(--faint);border-color:var(--border-v);background:none;cursor:default}\n  .meta{color:var(--faint);font-size:11.5px;margin-top:8px;font-family:var(--mono)}\n  details.read{margin-top:12px;color:var(--muted);font-size:12.5px;background:var(--bg2);border:1px solid var(--border);\n    border-radius:10px;padding:8px 12px}\n  details.read summary{cursor:pointer;color:var(--muted)}\n  details.read p{margin:.5em 0 0}\n  .src{background:var(--bg2);border:1px solid var(--border);border-radius:11px;padding:11px 13px;margin-bottom:9px;\n    transition:border-color .15s,box-shadow .15s}\n  .src.flash{border-color:var(--gold);box-shadow:0 0 0 1px var(--gold-dim)}\n  .src.dim{opacity:.55}\n  .src-head{display:flex;align-items:baseline;gap:8px;flex-wrap:wrap}\n  .num{font-family:var(--mono);font-size:11px;color:#1a1509;background:var(--gold);border-radius:4px;padding:0 5px;\n    cursor:pointer;border:none}\n  .tag{font-family:var(--mono);font-size:12px;color:var(--gold);font-weight:500}\n  .badge{font-size:10px;letter-spacing:.03em;border-radius:4px;padding:1px 6px;border:1px solid var(--border-v);\n    color:var(--muted);white-space:nowrap}\n  .badge.sc{color:var(--violet);border-color:var(--violet-dim)}\n  .badge.wit{color:var(--green);border-color:#3d5c35}\n  .badge.warn{color:var(--red);border-color:#6b3a2a}\n  .badge.ed{color:#d8b27a;border-color:var(--gold-dim)}\n  .open{margin-left:auto;font-size:11px;color:var(--muted)}\n  .dev{font-family:var(--dev);font-size:16px;line-height:1.75;color:#efe3c9;margin-top:7px;white-space:pre-wrap}\n  .iast{font-family:var(--serif);font-style:italic;font-size:15.5px;color:#d7cbb2;margin-top:5px;white-space:pre-wrap}\n  .clamp{display:-webkit-box;-webkit-line-clamp:4;-webkit-box-orient:vertical;overflow:hidden}\n  .more{background:none;border:none;color:var(--faint);font-size:11px;cursor:pointer;padding:0;margin-top:2px}\n  .more:hover{color:var(--gold)}\n  .en{font-family:var(--serif);font-size:16.5px;line-height:1.5;margin-top:7px;color:var(--ink)}\n  .en .lab{display:block;font-family:"Inter",sans-serif;font-size:10px;text-transform:uppercase;letter-spacing:.07em;\n    color:var(--faint);margin-bottom:1px}\n  .en.sc .lab{color:var(--violet)}\n  details.working{margin-top:5px;font-size:12px;color:var(--faint)}\n  details.working summary{cursor:pointer}\n  details.working div{font-family:var(--serif);font-size:15px;color:var(--muted);margin-top:3px}\n  .names{display:flex;flex-wrap:wrap;gap:5px;margin-top:8px}\n  .name{background:none;border:1px solid var(--border-v);color:var(--blue);border-radius:14px;padding:1px 9px;\n    font-size:11.5px;cursor:pointer}\n  .name:hover{border-color:var(--blue)}\n  .name i{color:var(--faint);font-style:normal;font-size:10px;margin-left:4px}\n  .hide-dev .dev,.hide-dev .more.for-dev{display:none}\n  .hide-iast .iast,.hide-iast .more.for-iast{display:none}\n  .hide-en .en,.hide-en details.working{display:none}\n  .skel{height:12px;border-radius:6px;background:linear-gradient(90deg,var(--bg3),var(--bg4),var(--bg3));\n    background-size:200% 100%;animation:sh 1.2s ease-in-out infinite;margin:9px 0}\n  @keyframes sh{0%{background-position:200% 0}100%{background-position:-200% 0}}\n  footer{color:var(--faint);font-size:11.5px;margin-top:36px;text-align:center;line-height:1.7}\n  @media (prefers-reduced-motion:reduce){*{animation:none!important;transition:none!important;scroll-behavior:auto!important}}\n  @media (max-width:600px){.wrap{padding:0 14px 48px}.ask-btn{margin-left:0;width:100%}.title{font-size:23px}}\n</style>\n</head>\n<body>\n<div class="wrap">\n  <header class="top">\n    <span class="om" aria-hidden="true">&#x0950;</span>\n    <div>\n      <div class="title">Ask the Corpus</div>\n      <div class="sub">An answer grounded in our verses, each claim cited; the verses beside it, in Sanskrit and English</div>\n    </div>\n    <nav class="nav" aria-label="Pages">\n      <a href="/">&larr; Dashboard</a>\n      <a href="/library">Library</a>\n    </nav>\n  </header>\n\n  <section class="askbox" aria-label="Your question">\n    <label for="q" class="lbl">Question</label>\n    <textarea id="q" placeholder="e.g.  What does the corpus say about the origin of the river Ga&#7749;g&#257;?"></textarea>\n    <div class="controls">\n      <label class="lbl" for="engine">Engine</label>\n      <select id="engine">\n        <option value="gemini:gemini-2.5-flash" selected>2.5 Flash</option>\n        <option value="gemini:gemini-2.5-pro">2.5 Pro (deeper)</option>\n        <option value="gemini:gemini-2.0-flash">2.0 Flash</option>\n      </select>\n      <span class="kwrap"><label class="lbl" for="k">Passages</label>\n        <input type="range" id="k" min="4" max="24" value="12"/>\n        <b id="kv" style="color:var(--gold)">12</b></span>\n      <span class="keys"><kbd>Ctrl</kbd>+<kbd>Enter</kbd> asks &middot; <kbd>/</kbd> to type</span>\n      <button class="ask-btn" id="askBtn" type="button">Ask &rarr;</button>\n    </div>\n    <div class="chips" id="examples" aria-label="Examples">\n      <span class="lbl">Try</span>\n      <button class="chip" type="button">the duties of a king toward his subjects</button>\n      <button class="chip" type="button">what is said about Naimi&#7779;&#257;ra&#7751;ya</button>\n      <button class="chip" type="button">Janaka and Y&#257;j&ntilde;avalkya</button>\n      <button class="chip" type="button">how did the rivers become goddesses</button>\n    </div>\n    <div class="chips" id="recent" aria-label="Your recent questions" hidden></div>\n  </section>\n\n  <div id="status" role="status" aria-live="polite"></div>\n  <div id="errBox"></div>\n\n  <main class="result" id="result" hidden>\n    <section class="answer-col" aria-label="Answer">\n      <div class="panel-head">\n        <h2>Answer</h2><span class="grow"></span>\n        <button class="tbtn" id="copyBtn" type="button" title="Copy the answer with its sources">Copy with sources</button>\n      </div>\n      <article class="answer-body" id="answerBody"></article>\n      <div class="meta" id="answerMeta"></div>\n      <details class="read" id="readBox">\n        <summary>What this answer read</summary>\n        <p id="readText"></p>\n      </details>\n    </section>\n    <aside class="sources-col" aria-label="Sources">\n      <div class="panel-head">\n        <h2 id="srcTitle">Sources</h2><span class="grow"></span>\n        <button class="tbtn" type="button" data-view="dev" aria-pressed="true">Devanagari</button>\n        <button class="tbtn" type="button" data-view="iast" aria-pressed="false">IAST</button>\n        <button class="tbtn" type="button" data-view="en" aria-pressed="true">English</button>\n      </div>\n      <div id="sources"></div>\n    </aside>\n  </main>\n\n  <footer>\n    The answer is generated from the corpus\'s English and may carry its limits; the verses beside it are the evidence.<br/>\n    Read each cited verse in the reader before you rely on it.\n  </footer>\n</div>\n\n<script>\n(function(){\n  "use strict";\n  var $ = function(id){ return document.getElementById(id); };\n  var SOURCES = [], LAST = null, timer = null;\n  var VIEW = {dev: true, iast: false, en: true};\n\n  function store(k, v){ try { if (v === undefined) return localStorage.getItem(k); localStorage.setItem(k, v); } catch(_){ return null; } }\n  function esc(s){ return (s == null ? "" : String(s)).replace(/[&<>"\']/g, function(c){\n    return {"&":"&amp;","<":"&lt;",">":"&gt;","\\"":"&quot;","\'":"&#39;"}[c]; }); }\n\n  /* preferences: the engine and the views, this browser only */\n  var e0 = store("askEngine"); if (e0) $("engine").value = e0;\n  $("engine").addEventListener("change", function(){ store("askEngine", this.value); });\n  try { var v0 = JSON.parse(store("askView") || "null"); if (v0) VIEW = Object.assign(VIEW, v0); } catch(_){}\n  function applyView(){\n    var s = $("sources");\n    s.classList.toggle("hide-dev", !VIEW.dev); s.classList.toggle("hide-iast", !VIEW.iast); s.classList.toggle("hide-en", !VIEW.en);\n    document.querySelectorAll("[data-view]").forEach(function(b){ b.setAttribute("aria-pressed", VIEW[b.dataset.view] ? "true" : "false"); });\n  }\n  document.querySelectorAll("[data-view]").forEach(function(b){\n    b.addEventListener("click", function(){ VIEW[b.dataset.view] = !VIEW[b.dataset.view]; store("askView", JSON.stringify(VIEW)); applyView(); });\n  });\n  applyView();\n\n  $("k").addEventListener("input", function(){ $("kv").textContent = this.value; });\n  $("q").addEventListener("keydown", function(ev){\n    if (ev.key === "Enter" && (ev.ctrlKey || ev.metaKey)) { ev.preventDefault(); ask(); }\n  });\n  document.addEventListener("keydown", function(ev){\n    var t = ev.target && ev.target.tagName;\n    if (ev.key === "/" && t !== "TEXTAREA" && t !== "INPUT" && t !== "SELECT") { ev.preventDefault(); $("q").focus(); }\n  });\n  $("askBtn").addEventListener("click", ask);\n  $("examples").addEventListener("click", function(ev){\n    var b = ev.target.closest(".chip"); if (b) { setQ(b.textContent); }\n  });\n  function setQ(text){ $("q").value = text; $("q").focus(); }\n\n  /* recent questions, this browser only */\n  function recent(){ try { return JSON.parse(store("askRecent") || "[]") || []; } catch(_){ return []; } }\n  function remember(q){\n    var r = recent().filter(function(x){ return x !== q; }); r.unshift(q); store("askRecent", JSON.stringify(r.slice(0, 8))); drawRecent();\n  }\n  function drawRecent(){\n    var r = recent(), box = $("recent");\n    if (!r.length) { box.hidden = true; box.innerHTML = ""; return; }\n    box.hidden = false;\n    box.innerHTML = \'<span class="lbl">Recent</span>\' + r.map(function(x){\n      return \'<button class="chip" type="button" data-q="\' + esc(x) + \'">\' + esc(x.length > 60 ? x.slice(0, 58) + "\\u2026" : x) + \'</button>\';\n    }).join("") + \'<button class="chip clear" type="button" data-clear="1">clear</button>\';\n  }\n  $("recent").addEventListener("click", function(ev){\n    var b = ev.target.closest(".chip"); if (!b) return;\n    if (b.dataset.clear) { store("askRecent", "[]"); drawRecent(); return; }\n    setQ(b.dataset.q || b.textContent);\n  });\n  drawRecent();\n\n  /* the answer: a little markdown, and each [tag] or [n] a numbered citation */\n  function findSource(tag){\n    var t = tag.trim(); if (!t) return -1;\n    if (/^\\d{1,2}$/.test(t)) { var n = parseInt(t, 10); return (n >= 1 && n <= SOURCES.length) ? n : -1; }\n    for (var i = 0; i < SOURCES.length; i++) { if (SOURCES[i].tag === t) return SOURCES[i].n; }\n    var lt = t.toLowerCase();\n    for (var j = 0; j < SOURCES.length; j++) { if (String(SOURCES[j].tag).toLowerCase() === lt) return SOURCES[j].n; }\n    return -1;\n  }\n  function cites(html){\n    return html.replace(/\\[([^\\[\\]]{1,160})\\]/g, function(m, inner){\n      var whole = findSource(inner);\n      if (whole > 0) return \'<a class="cite" href="#src-\' + whole + \'" data-n="\' + whole + \'" title="\' + esc(SOURCES[whole - 1].tag) + \'">\' + whole + \'</a>\';\n      var parts = inner.split(/\\s*[;,]\\s*(?=\\S)/), out = [], any = false;\n      parts.forEach(function(p){\n        var n = findSource(p);\n        if (n > 0) { any = true; out.push(\'<a class="cite" href="#src-\' + n + \'" data-n="\' + n + \'" title="\' + esc(SOURCES[n - 1].tag) + \'">\' + n + \'</a>\'); }\n        else out.push(null);\n      });\n      if (!any) return \'<span class="cite unknown" title="not among the sources">\' + m + \'</span>\';\n      return out.map(function(x, i){ return x || (\'<span class="cite unknown">\' + parts[i] + \'</span>\'); }).join("");\n    });\n  }\n  function inline(s){\n    return cites(s).replace(/\\*\\*([^*]+)\\*\\*/g, "<strong>$1</strong>").replace(/(^|[\\s(])\\*([^*\\s][^*]*)\\*(?=[\\s).,;:!?]|$)/g, "$1<em>$2</em>");\n  }\n  function renderAnswer(text){\n    var lines = esc(text).replace(/\\r/g, "").split("\\n"), html = "", para = [], list = null;\n    function flushP(){ if (para.length) { html += "<p>" + inline(para.join("<br/>")) + "</p>"; para = []; } }\n    function flushL(){ if (list) { html += "<" + list.t + ">" + list.items.map(function(x){ return "<li>" + inline(x) + "</li>"; }).join("") + "</" + list.t + ">"; list = null; } }\n    lines.forEach(function(raw){\n      var l = raw.replace(/\\s+$/, ""), m;\n      if (!l.trim()) { flushP(); flushL(); return; }\n      if ((m = l.match(/^\\s*#{1,4}\\s+(.*)$/))) { flushP(); flushL(); html += "<h4>" + inline(m[1]) + "</h4>"; return; }\n      if ((m = l.match(/^\\s*(?:[-*\\u2022])\\s+(.*)$/))) { flushP(); if (!list || list.t !== "ul") { flushL(); list = {t: "ul", items: []}; } list.items.push(m[1]); return; }\n      if ((m = l.match(/^\\s*\\d{1,2}[.)]\\s+(.*)$/))) { flushP(); if (!list || list.t !== "ol") { flushL(); list = {t: "ol", items: []}; } list.items.push(m[1]); return; }\n      flushL(); para.push(l);\n    });\n    flushP(); flushL();\n    $("answerBody").innerHTML = html || \'<p style="color:var(--muted)">(no text)</p>\';\n  }\n\n  /* the sources */\n  function badge(cls, text, title){ return \'<span class="badge \' + cls + \'"\' + (title ? \' title="\' + esc(title) + \'"\' : "") + ">" + esc(text) + "</span>"; }\n  function short(engine){ return String(engine || "").replace(/^[a-z-]+:/, ""); }\n  function clampBlock(cls, text, lang, forWhat){\n    var long = text.length > 260;\n    return \'<div class="\' + cls + (long ? " clamp" : "") + \'" lang="\' + lang + \'">\' + esc(text) + "</div>"\n      + (long ? \'<button class="more for-\' + forWhat + \'" type="button">more</button>\' : "");\n  }\n  function renderSources(sources){\n    SOURCES = sources || [];\n    $("srcTitle").textContent = SOURCES.length ? "Sources (" + SOURCES.length + ")" : "Sources";\n    $("sources").innerHTML = SOURCES.map(function(s){\n      var ed = !!(s.kind || s.link), b = [];\n      if (ed) b.push(badge("ed", "editorial: " + (s.label || s.kind || "item"), "made from this corpus by the project; not scripture"));\n      if (s.witness) b.push(badge("wit", "e-text witness", "a typed edition read beside our scan"));\n      if (s.scholar) b.push(badge("sc", "scholarly " + (s.scholar_state || ""), short(s.scholar_engine)));\n      if (s.ocr) b.push(badge("", "read by " + short(s.ocr), "how the Sanskrit was read"));\n      if (s.state) b.push(badge(s.state === "withdrawn" || s.state === "set_aside" ? "warn" : "", s.state.replace(/_/g, " "), "its state in the register"));\n      /* BRAIN_ITEMS_2026_10_07: an editorial item opens its story, episode or picture */\n      var href = s.link ? esc(s.link) : "/reader/" + encodeURIComponent(s.doc || "");\n      var h = \'<article class="src" id="src-\' + s.n + \'" data-n="\' + s.n + \'" tabindex="-1">\'\n        + \'<div class="src-head"><button class="num" type="button" data-n="\' + s.n + \'" title="show where the answer cites it">\' + s.n + "</button>"\n        + \'<span class="tag">\' + esc(s.tag) + "</span>" + b.join("")\n        + \'<a class="open" href="\' + href + \'" target="_blank" rel="noopener">\' + (s.link ? "open" : "reader") + " \\u2197</a></div>";\n      if (s.sanskrit) h += clampBlock("dev", s.sanskrit, "sa", "dev");\n      if (s.iast) h += clampBlock("iast", s.iast, "sa-Latn", "iast");\n      if (s.scholar) {\n        h += \'<div class="en sc"><span class="lab">Scholarly English</span>\' + esc(s.scholar) + "</div>";\n        if (s.english) h += \'<details class="working"><summary>the working English\' + (s.mt ? " (" + esc(short(s.mt)) + ")" : "") + ", which the answer read</summary><div>" + esc(s.english) + "</div></details>";\n      } else if (s.english) {\n        h += \'<div class="en"><span class="lab">\' + (ed ? "Editorial" : "Working English" + (s.mt ? " \\u00b7 " + esc(short(s.mt)) : "")) + "</span>" + esc(s.english) + "</div>";\n      }\n      if (s.names && s.names.length) {\n        h += \'<div class="names">\' + s.names.map(function(x){\n          return \'<button class="name" type="button" data-name="\' + esc(x.name) + \'" title="ask about \' + esc(x.name) + \'">\' + esc(x.name) + (x.kind ? "<i>" + esc(x.kind) + "</i>" : "") + "</button>";\n        }).join("") + "</div>";\n      }\n      return h + "</article>";\n    }).join("");\n    applyView();\n  }\n  $("sources").addEventListener("click", function(ev){\n    var more = ev.target.closest(".more");\n    if (more) { var blk = more.previousElementSibling; if (blk) { var open = blk.classList.toggle("clamp"); more.textContent = open ? "more" : "less"; } return; }\n    var nm = ev.target.closest(".name");\n    if (nm) { setQ("What does the corpus say about " + nm.dataset.name + "?"); window.scrollTo({top: 0, behavior: smooth()}); return; }\n    var num = ev.target.closest(".num");\n    if (num) { light(num.dataset.n); }\n  });\n  $("answerBody").addEventListener("click", function(ev){\n    var c = ev.target.closest(".cite[data-n]"); if (!c) return;\n    ev.preventDefault(); jump(c.dataset.n);\n  });\n  function smooth(){ return window.matchMedia && window.matchMedia("(prefers-reduced-motion: reduce)").matches ? "auto" : "smooth"; }\n  function jump(n){\n    var el = $("src-" + n); if (!el) return;\n    el.scrollIntoView({behavior: smooth(), block: "nearest"});\n    el.classList.add("flash"); el.focus({preventScroll: true});\n    setTimeout(function(){ el.classList.remove("flash"); }, 1500);\n    light(n);\n  }\n  function light(n){\n    document.querySelectorAll(".cite.lit").forEach(function(x){ x.classList.remove("lit"); });\n    var first = null;\n    document.querySelectorAll(\'.cite[data-n="\' + n + \'"]\').forEach(function(x){ x.classList.add("lit"); first = first || x; });\n    if (first && !isVisible(first)) first.scrollIntoView({behavior: smooth(), block: "center"});\n  }\n  function isVisible(el){ var r = el.getBoundingClientRect(); return r.top >= 0 && r.bottom <= (window.innerHeight || 0); }\n\n  /* what the answer read: said plainly, from what came back */\n  function readText(d){\n    var v = (d.sources || []).filter(function(s){ return !(s.kind || s.link); }).length, e = d.editorial || 0;\n    return "The model was given the working English of the " + v + " passages listed (up to 600 characters of each)"\n      + (e ? " and " + e + " editorial item" + (e > 1 ? "s" : "") + " marked so" : "")\n      + ", found by " + (d.mode === "semantic" ? "meaning" : "keyword") + " search. It was not given the Sanskrit, the scholarly English,"\n      + " the names or the scholars\' claims: they are shown here for you to check it (phase A1, ask-v2, gives the model these).";\n  }\n\n  $("copyBtn").addEventListener("click", function(){\n    if (!LAST) return;\n    var t = (LAST.answer || "") + "\\n\\nSources\\n" + (LAST.sources || []).map(function(s){\n      return "[" + s.n + "] " + s.tag + " \\u2014 " + String(s.scholar || s.english || "").slice(0, 180).replace(/\\s+/g, " ");\n    }).join("\\n");\n    var done = function(){ $("copyBtn").textContent = "Copied"; setTimeout(function(){ $("copyBtn").textContent = "Copy with sources"; }, 1400); };\n    if (navigator.clipboard && navigator.clipboard.writeText) navigator.clipboard.writeText(t).then(done, function(){});\n  });\n\n  function busy(on){\n    var st = $("status");\n    if (timer) { clearInterval(timer); timer = null; }\n    if (!on) { st.innerHTML = ""; return; }\n    var t0 = Date.now();\n    var draw = function(){ st.innerHTML = \'<span class="spinner"></span>Finding the verses by meaning and composing a cited answer&hellip; \'\n      + Math.round((Date.now() - t0) / 1000) + " s"; };\n    draw(); timer = setInterval(draw, 1000);\n  }\n  function skeleton(){\n    $("answerBody").innerHTML = \'<div class="skel" style="width:92%"></div><div class="skel" style="width:85%"></div><div class="skel" style="width:60%"></div>\';\n    $("sources").innerHTML = ""; $("answerMeta").textContent = ""; $("result").hidden = false;\n  }\n\n  async function ask(){\n    var q = $("q").value.trim(); $("errBox").innerHTML = "";\n    if (!q) { $("q").focus(); return; }\n    var btn = $("askBtn"); btn.disabled = true; busy(true); skeleton();\n    try {\n      var r = await fetch("/api/ask", {method: "POST", headers: {"Content-Type": "application/json"},\n        body: JSON.stringify({q: q, engine: $("engine").value, k: parseInt($("k").value, 10)})});\n      var d = {};\n      try { d = await r.json(); } catch(_){ d = {error: "HTTP " + r.status}; }\n      busy(false);\n      remember(q);\n      if (!r.ok || d.error) {\n        $("errBox").innerHTML = \'<div class="err"><b>Could not answer:</b> \' + esc(d.error || ("HTTP " + r.status))\n          + (d.error && d.error.indexOf("GEMINI_API_KEY") >= 0 ? "<br/>Set <code>GEMINI_API_KEY</code> in the project <code>.env</code> and restart the dashboard." : "") + "</div>";\n        if (d.sources && d.sources.length) {\n          renderSources(d.sources);\n          $("answerBody").innerHTML = \'<p style="color:var(--muted)">No answer was composed. The passages found are beside it.</p>\';\n          $("answerMeta").textContent = ""; $("readText").textContent = ""; $("result").hidden = false; LAST = null;\n        } else { $("result").hidden = true; }\n        return;\n      }\n      LAST = d;\n      renderSources(d.sources);\n      renderAnswer(d.answer || "");\n      var nv = (d.sources || []).length;\n      $("answerMeta").textContent = nv + " sources \\u00b7 " + (d.mode === "semantic" ? "meaning search" : "keyword search")\n        + (d.editorial ? " \\u00b7 " + d.editorial + " editorial" : "") + (d.engine ? " \\u00b7 " + short(d.engine) : "");\n      $("readText").textContent = readText(d);\n      $("result").hidden = false;\n      $("result").scrollIntoView({behavior: smooth(), block: "start"});\n    } catch (e) {\n      busy(false); $("result").hidden = true;\n      $("errBox").innerHTML = \'<div class="err">The request failed: \' + esc(e.message || e) + "</div>";\n    } finally { btn.disabled = false; }\n  }\n})();\n</script>\n</body>')

